/* Approval list prototype. Records and workflow actions are local demonstration data. */
(function(global){
  'use strict';
  global.createApprovalPage=function({esc,drawer,closeDrawer,notify,render,openAdjustment}){
    const state={tab:'pending',keyword:'预算调整',time:'全部',start:'',end:'',type:'全部',overseas:'全部',invoice:'全部',tag:'全部',applicant:'',department:'',more:false,selected:new Set(),expanded:new Set(),page:1,size:20,sort:'date',descending:true};
    const records=[
      {id:'adj1',number:'20260828164150628186',title:'吴极客发起的团队预算调整申请单',person:'吴极客',employeeNo:'B04141',department:'博商深圳/博商科技/质量部',created:'2026-08-28 16:41:42',date:'2026-08-28 16:41:50',status:'待审批',statusTime:'2026-08-28 16:41:51',approver:'超级管理员(B00000)',mine:true,cc:false,tags:[],reason:'根据秋季课程及招生计划调整9—11月预算：增加宣传投放、异地课程差旅、招生活动及讲师课酬；办公设备采购延后，释放部分办公预算。各科目具体调整原因见下方明细。',history:[]},
      {id:'adj2',number:'20260825101530628152',title:'张敏发起的团队预算调整申请单',person:'张敏',employeeNo:'B04231',department:'博商深圳/运营部',created:'2026-08-25 10:15:20',date:'2026-08-25 10:15:30',status:'已同意',statusTime:'2026-08-25 11:08:16',approver:'超级管理员(B00000)',mine:true,cc:false,tags:['合适的'],reason:'根据业务排期调整预算分配。',history:[{time:'2026-08-25 11:08:16',text:'超级管理员同意申请'}]},
      {id:'adj3',number:'20260827143020628174',title:'李倩发起的团队预算调整申请单',person:'李倩',employeeNo:'B03618',department:'博商深圳/财务部',created:'2026-08-27 14:30:12',date:'2026-08-27 14:30:20',status:'待审批',statusTime:'2026-08-27 14:30:21',approver:'陈杰(B02847)',mine:false,cc:true,tags:[],reason:'补充团队预算调整说明。',history:[]}
    ];
    const initialState=structuredClone(state),initialRecords=structuredClone(records);
    const find=id=>records.find(r=>r.id===id);
    const now=()=>new Date().toLocaleString('sv-SE');
    function filtered(){
      return records.filter(r=>(state.tab==='pending'?r.mine&&r.status==='待审批':state.tab==='processed'?r.mine&&r.status!=='待审批':state.tab==='copied'?r.cc:r.status==='待审批')&&(!state.keyword||`${r.number}${r.title}团队预算调整申请单`.includes(state.keyword))&&(!state.start||r.date.slice(0,10)>=state.start)&&(!state.end||r.date.slice(0,10)<=state.end)&&state.type==='全部'&&state.overseas!=='是'&&state.invoice!=='是'&&(state.tag==='全部'||r.tags.includes(state.tag))&&(!state.applicant||`${r.person}${r.employeeNo}`.includes(state.applicant))&&(!state.department||r.department.includes(state.department))).sort((a,b)=>(state.descending?-1:1)*(a[state.sort]||'').localeCompare(b[state.sort]||''));
    }
    const choices=(key,items)=>items.map(label=>`<button type="button" class="approval-choice ${state[key]===label?'active':''}" data-action="approval-filter" data-key="${key}" data-value="${esc(label)}">${esc(label)}</button>`).join('');
    const action=(label,kind,r)=>`<button type="button" data-action="approval-${kind}" data-id="${r.id}">${label}</button>`;
    function row(r){
      const canAct=r.status==='待审批'&&r.mine;
      return `<tr><td><input type="checkbox" data-approval-check="${r.id}" aria-label="选择单据${r.number}" ${state.selected.has(r.id)?'checked':''}></td><td><div class="approval-row-actions">${action('详情','detail',r)}${action('日志','log',r)}${canAct?action('同意','agree',r)+action('驳回','reject',r)+action('转审','transfer',r)+action('加签','countersign',r):''}${action('标签','tag',r)}</div></td><td>${r.number}</td><td>${action(esc(r.title),'detail',r)}</td><td>--</td><td>--</td><td>${r.date}</td><td>${esc(r.person)}</td><td>${esc(r.department)}</td><td></td><td><div class="approval-content">标题：${esc(r.title)}<br>申请时间：${r.created}${state.expanded.has(r.id)?`<br>申请人：${esc(r.person)}（${r.employeeNo}）<br>调整说明：${esc(r.reason)}`:''}<button type="button" class="approval-content-toggle" data-action="approval-expand" data-id="${r.id}" aria-label="${state.expanded.has(r.id)?'收起':'展开'}申请内容" aria-expanded="${state.expanded.has(r.id)}">${state.expanded.has(r.id)?'⌃':'⌄'}</button></div></td><td>--</td><td>--</td><td>团队预算调整申请单</td><td>${esc(r.status)}</td><td>${r.statusTime}</td><td>--</td><td>${esc(r.approver)}</td><td>${esc(r.tags.join('、'))}</td></tr>`;
    }
    function renderPage(){
      const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/state.size));state.page=Math.min(state.page,pages);
      const shown=rows.slice((state.page-1)*state.size,state.page*state.size),checked=shown.length>0&&shown.every(r=>state.selected.has(r.id));
      return `<section class="approval-page" aria-label="审批"><div class="approval-toolbar"><div class="approval-tabs" role="tablist" aria-label="审批申请单分类">${[['pending','待审批申请单'],['processed','已审批申请单'],['copied','抄送我的申请单'],['all','全部待审批申请单']].map(([id,label])=>`<button role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'active':''}" data-action="approval-tab" data-tab="${id}">${label}</button>`).join('')}</div><div class="approval-search"><div><input id="approval-search" aria-label="搜索单号或标题" value="${esc(state.keyword)}" placeholder="单号／标题"><button data-action="approval-query" aria-label="搜索">⌕</button></div><button class="approval-red" data-action="approval-more" aria-expanded="${state.more}">更多☰</button></div></div><div class="approval-filters"><div class="approval-filter-row"><strong>创建时间：</strong><div class="approval-filter-options">${choices('time',['全部','昨天','今天','本周','上周','本月','上月','本季度','上季度','本年','去年'])}<label class="approval-date"><input type="date" id="approval-start" aria-label="创建开始日期" value="${state.start}"></label><span>到</span><label class="approval-date"><input type="date" id="approval-end" aria-label="创建结束日期" value="${state.end}"></label><button class="approval-red" data-action="approval-query">查询</button></div></div><div class="approval-filter-row"><strong>单据类型：</strong><div class="approval-filter-options">${choices('type',['全部','报销单类型','售后单类型'])}</div></div><div class="approval-filter-row"><strong>是否涉及海外：</strong><div class="approval-filter-options">${choices('overseas',['全部','是','否'])}</div></div><div class="approval-filter-row"><strong>是否有发票：</strong><div class="approval-filter-options">${choices('invoice',['全部','是','否'])}</div></div><div class="approval-filter-row"><strong>标　签：</strong><div class="approval-filter-options">${choices('tag',['全部','3333','合适的','11112312'])}</div></div>${state.more?`<div class="approval-filter-row approval-more-row"><strong>更多条件：</strong><div class="approval-filter-options"><label>申请人 <input id="approval-applicant" value="${esc(state.applicant)}" placeholder="姓名／工号"></label><label>申请部门 <input id="approval-department" value="${esc(state.department)}" placeholder="部门名称"></label><button class="approval-red" data-action="approval-query">查询</button><button data-action="approval-reset">重置</button></div></div>`:''}</div><div class="approval-bulk"><button data-action="approval-print" ${state.selected.size?'':'disabled'}>批量打印</button><span>（当前已选${state.selected.size}条，最多可选30条）</span></div><div class="table-wrap approval-table-wrap"><table class="approval-table"><thead><tr><th><input type="checkbox" id="approval-check-all" aria-label="全选当前页申请单" ${checked?'checked':''}></th><th>操作</th><th>单号</th><th>标题</th><th>是否有发票</th><th>是否涉及海外</th><th><button data-action="approval-sort" data-key="date">申请时间${state.sort==='date'?(state.descending?'⌄':'⌃'):''}</button></th><th><button data-action="approval-sort" data-key="person">申请人${state.sort==='person'?(state.descending?'⌄':'⌃'):''}</button></th><th>申请部门</th><th>付款主体</th><th>内容</th><th>金额(人民币)</th><th>金额(外币)</th><th>单据类型</th><th>状态</th><th>状态时间</th><th>失败原因</th><th>审批人</th><th>流程标签</th></tr></thead><tbody>${shown.map(row).join('')}</tbody></table></div>${rows.length?'':'<div class="approval-empty">暂无符合条件的申请单</div>'}<div class="approval-pagination"><button data-action="approval-page" data-page="1" ${state.page===1?'disabled':''}>首页</button><button data-action="approval-page" data-page="${state.page-1}" ${state.page===1?'disabled':''}>前一页</button><button class="current" aria-current="page">${state.page}</button><button data-action="approval-page" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>下一页</button><button data-action="approval-page" data-page="${pages}" ${state.page>=pages?'disabled':''}>尾页</button><select id="approval-page-size" aria-label="每页条数">${[20,30,50].map(n=>`<option ${n===state.size?'selected':''}>${n}</option>`).join('')}</select><span>条/每页　第</span><input id="approval-page-number" aria-label="跳转页码" type="number" min="1" max="${pages}" value="${state.page}"><span>页　总共 ${rows.length} 条</span></div></section>`;
    }
    function detail(r){openAdjustment(r.id);}
    function readQuery(){
      state.keyword=$value('approval-search',state.keyword);state.start=$value('approval-start',state.start);state.end=$value('approval-end',state.end);state.applicant=$value('approval-applicant',state.applicant);state.department=$value('approval-department',state.department);
      if(state.start&&state.end&&state.start>state.end){notify('开始日期不能晚于结束日期');return;}state.selected.clear();state.page=1;render();
    }
    const $value=(id,fallback)=>document.getElementById(id)?.value.trim()??fallback;
    function dateRange(label){
      const today=new Date(),base=new Date(today.getFullYear(),today.getMonth(),today.getDate()),start=new Date(base),end=new Date(base),day=(base.getDay()+6)%7;
      switch(label){case '全部':return ['',''];case '昨天':start.setDate(start.getDate()-1);end.setDate(end.getDate()-1);break;case '本周':start.setDate(start.getDate()-day);end.setTime(start.getTime());end.setDate(end.getDate()+6);break;case '上周':start.setDate(start.getDate()-day-7);end.setTime(start.getTime());end.setDate(end.getDate()+6);break;case '本月':start.setDate(1);end.setMonth(end.getMonth()+1,0);break;case '上月':start.setMonth(start.getMonth()-1,1);end.setDate(0);break;case '本季度':start.setMonth(Math.floor(start.getMonth()/3)*3,1);end.setMonth(start.getMonth()+3,0);break;case '上季度':start.setMonth(Math.floor(start.getMonth()/3)*3-3,1);end.setTime(start.getTime());end.setMonth(end.getMonth()+3,0);break;case '本年':start.setMonth(0,1);end.setMonth(11,31);break;case '去年':start.setFullYear(start.getFullYear()-1,0,1);end.setFullYear(end.getFullYear()-1,11,31);break;}
      const format=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return [format(start),format(end)];
    }
    function handleClick(button){
      const action=button.dataset.action,r=find(button.dataset.id);
      switch(action){
        case 'approval-tab':state.tab=button.dataset.tab;state.selected.clear();state.page=1;render();break;
        case 'approval-query':readQuery();break;
        case 'approval-more':state.keyword=$value('approval-search',state.keyword);state.more=!state.more;render();break;
        case 'approval-filter':state[button.dataset.key]=button.dataset.value;if(button.dataset.key==='time')[state.start,state.end]=dateRange(state.time);state.selected.clear();state.page=1;render();break;
        case 'approval-reset':Object.assign(state,{keyword:'预算调整',time:'全部',start:'',end:'',type:'全部',overseas:'全部',invoice:'全部',tag:'全部',applicant:'',department:'',page:1});state.selected.clear();render();break;
        case 'approval-page':state.page=Number(button.dataset.page);render();break;
        case 'approval-sort':state.descending=state.sort===button.dataset.key?!state.descending:true;state.sort=button.dataset.key;render();break;
        case 'approval-detail':if(r)detail(r);break;
        case 'approval-expand':if(r){state.expanded.has(r.id)?state.expanded.delete(r.id):state.expanded.add(r.id);render();}break;
        case 'approval-log':if(r)drawer('审批日志',r.number,`<div class="timeline"><div>申请人提交<p>${r.date} · ${esc(r.person)}</p></div>${r.history.map(h=>`<div>${esc(h.text)}<p>${h.time}</p></div>`).join('')}${r.status==='待审批'?`<div>待审批<p>${esc(r.approver)}</p></div>`:''}</div>`);break;
        case 'approval-agree':case 'approval-reject':case 'approval-transfer':case 'approval-countersign':case 'approval-tag':
          if(!r)return;
          if(action!=='approval-tag'&&(r.status!=='待审批'||!r.mine)){notify('该申请单当前无需您审批');return;}
          {const kind=action.slice(9),label={agree:'同意',reject:'驳回',transfer:'转审',countersign:'加签',tag:'标签'}[kind];drawer(`${label}申请单`,r.number,kind==='tag'?`<label class="approval-dialog-field">流程标签<input id="approval-action-value" value="${esc(r.tags.join('、'))}" placeholder="多个标签以顿号分隔"></label>`:['transfer','countersign'].includes(kind)?'<label class="approval-dialog-field">处理人<select id="approval-action-value"><option>李倩(B03618)</option><option>陈杰(B02847)</option><option>张敏(B04231)</option></select></label>':`<label class="approval-dialog-field">审批意见${kind==='reject'?'（必填）':''}<textarea id="approval-action-value" rows="4" placeholder="请输入审批意见"></textarea></label>`,`<button class="primary" data-action="approval-confirm" data-id="${r.id}" data-kind="${kind}">确认${label}</button>`);}break;
        case 'approval-confirm':{
          if(!r)return;const kind=button.dataset.kind,value=$value('approval-action-value','');if(kind==='reject'&&!value){notify('请填写驳回意见');return;}
          if(kind==='tag')r.tags=value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean);else{if(r.status!=='待审批'){notify('该申请单已处理');return;}r.statusTime=now();if(kind==='agree'||kind==='reject')r.status=kind==='agree'?'已同意':'已驳回';if(kind==='transfer'){r.approver=value;r.mine=false;}if(kind==='countersign')r.approver+='、'+value;r.history.push({time:r.statusTime,text:{agree:'超级管理员同意申请',reject:'超级管理员驳回申请',transfer:'转审至',countersign:'加签审批人'}[kind]+(value?'：'+value:'')});}state.selected.delete(r.id);closeDrawer();render();notify('操作已在原型中更新');break;
        }
        case 'approval-print':{const selected=records.filter(r=>state.selected.has(r.id));if(!selected.length)return;drawer('批量打印预览',`已选 ${selected.length} 条申请单`,selected.map(r=>`<article class="approval-print-sheet"><h3>团队预算调整申请单</h3><p>${r.number}</p><p>${esc(r.title)}</p><p>申请人：${esc(r.person)}（${r.employeeNo}）</p><p>申请部门：${esc(r.department)}</p><p>申请时间：${r.date}</p><p>状态：${r.status}</p></article>`).join(''),'<button class="primary" data-action="approval-print-confirm">打印</button>',true);break;}
        case 'approval-print-confirm':global.print();break;
      }
    }
    function handleChange(el){
      if(el.dataset.approvalCheck){if(el.checked&&state.selected.size>=30){el.checked=false;notify('最多选择30条申请单');return;}el.checked?state.selected.add(el.dataset.approvalCheck):state.selected.delete(el.dataset.approvalCheck);render();}
      else if(el.id==='approval-check-all'){const shown=filtered().slice((state.page-1)*state.size,state.page*state.size);for(const r of shown){if(el.checked&&state.selected.size<30)state.selected.add(r.id);if(!el.checked)state.selected.delete(r.id);}render();}
      else if(el.id==='approval-page-size'){state.size=Number(el.value);state.page=1;render();}
      else if(el.id==='approval-page-number'){state.page=Math.max(1,Math.min(Math.ceil(filtered().length/state.size)||1,Number(el.value)||1));render();}
      else if(el.id==='approval-start'||el.id==='approval-end'){state.start=$value('approval-start','');state.end=$value('approval-end','');state.time='自定义';}
    }
    function reset(){Object.assign(state,structuredClone(initialState));records.splice(0,records.length,...structuredClone(initialRecords));}
    return {render:renderPage,click:handleClick,change:handleChange,query:readQuery,reset,record:find,add:record=>{records.unshift(record);}};
  };
})(window);
